_PRECEDENCE = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3}


def _is_digit(char: str) -> bool:
    return "0" <= char <= "9"


def _tokenize(expression: str) -> list:
    tokens = []
    index = 0
    length = len(expression)
    while index < length:
        char = expression[index]
        if char == " ":
            index += 1
            continue
        if _is_digit(char):
            start = index
            while index < length and _is_digit(expression[index]):
                index += 1
            if index < length and expression[index] == ".":
                index += 1
                fraction_start = index
                while index < length and _is_digit(expression[index]):
                    index += 1
                if index == fraction_start:
                    raise ValueError("invalid number: missing digits after decimal point")
                tokens.append(("num", float(expression[start:index])))
            else:
                tokens.append(("num", int(expression[start:index])))
            continue
        if char in "+-*/()":
            tokens.append(("op", char))
            index += 1
            continue
        raise ValueError(f"unknown character: {char!r}")
    return tokens


def _to_postfix(tokens: list) -> list:
    output = []
    operators = []
    expect_operand = True
    for kind, token in tokens:
        if expect_operand:
            if kind == "num":
                output.append(("num", token))
                expect_operand = False
            elif token == "-":
                operators.append("neg")
            elif token == "(":
                operators.append("(")
            else:
                raise ValueError(f"unexpected token: {token!r}")
        else:
            if kind == "num" or token == "(":
                raise ValueError("missing operator")
            if token == ")":
                while operators and operators[-1] != "(":
                    output.append(("op", operators.pop()))
                if not operators:
                    raise ValueError("unmatched closing parenthesis")
                operators.pop()
            else:
                precedence = _PRECEDENCE[token]
                while (
                    operators
                    and operators[-1] != "("
                    and _PRECEDENCE[operators[-1]] >= precedence
                ):
                    output.append(("op", operators.pop()))
                operators.append(token)
                expect_operand = True
    if expect_operand:
        raise ValueError("incomplete expression")
    while operators:
        operator = operators.pop()
        if operator == "(":
            raise ValueError("unmatched opening parenthesis")
        output.append(("op", operator))
    return output


def _evaluate_postfix(postfix: list) -> int | float:
    values = []
    for kind, item in postfix:
        if kind == "num":
            values.append(item)
            continue
        if item == "neg":
            if not values:
                raise ValueError("invalid expression")
            values.append(-values.pop())
            continue
        if len(values) < 2:
            raise ValueError("invalid expression")
        right = values.pop()
        left = values.pop()
        if item == "+":
            values.append(left + right)
        elif item == "-":
            values.append(left - right)
        elif item == "*":
            values.append(left * right)
        else:
            if right == 0:
                raise ZeroDivisionError("division by zero")
            values.append(left / right)
    if len(values) != 1:
        raise ValueError("invalid expression")
    return values[0]


def evaluate(expression: str) -> int | float:
    if not isinstance(expression, str):
        raise ValueError("expression must be a string")
    tokens = _tokenize(expression)
    postfix = _to_postfix(tokens)
    return _evaluate_postfix(postfix)
